function Scene({ width, height, scale }) {
  const frame = useCurrentFrame();
  const u = Math.min(width, height * 1.4) / 10;
  const coin = fall(frame, 20, 18, 240 * scale);
  const lit = progress(frame, 50, 20);
  return (
    <AbsoluteFill>
      <svg width={width} height={height}>
        <Disc cx={width / 2} cy={height * 0.5} r={height * 0.42} />
        <g transform={`translate(${width / 2 - u} ${height * 0.62})`}>
          <IsoShadow x={1} y={1} r={1.8} unit={u} />
          <IsoHouse x={0} y={0} unit={u} lit={lit} />
          <IsoCoinStack x={3.2} y={0.8} count={4} unit={u} />
          <g transform={`translate(0 ${coin.y})`} opacity={coin.opacity}><IsoCoin x={3.2} y={0.8} z={0.8} unit={u} /></g>
        </g>
      </svg>
    </AbsoluteFill>
  );
}

