function Scene({ width, height, scale }) {
  const frame = useCurrentFrame();
  const t = progress(frame, 6, 14);
  const w = 190 * scale;
  const h = 300 * scale;
  const card = (fill, dx, rot) => (
    <g transform={`translate(${width / 2 + dx * t} ${height * 0.5}) rotate(${rot * t})`}>
      <rect x={-w / 2} y={-h / 2} width={w} height={h} rx={16 * scale} fill={fill} />
      <rect x={-w / 2 + 110 * scale} y={-h / 2 + 50 * scale} width={40 * scale} height={32 * scale} rx={6 * scale} fill={palette.white} opacity={0.55} />
    </g>
  );
  return (
    <AbsoluteFill>
      <svg width={width} height={height}>
        <ellipse cx={width / 2} cy={height * 0.5 + h * 0.56} rx={w * 1.3} ry={16 * scale} fill={palette.shadow} opacity={0.45} />
        {card("#C8C8CC", 80 * scale, 10)}
        {card("#D9B27C", -80 * scale, -10)}
      </svg>
    </AbsoluteFill>
  );
}

function Scene({ width, height, scale }) {
  const frame = useCurrentFrame();
  const u = Math.min(width, height * 1.4) / 11;
  const bus = slideAlongIso(frame, 8, 30, [5, 0, 0], u);
  const plane = slideIn(frame, 24, 30, [-260 * scale, 120 * scale]);
  return (
    <AbsoluteFill>
      <svg width={width} height={height}>
        <g transform={`translate(${width / 2 - 2 * u} ${height * 0.56})`}>
          <g transform={`translate(${bus.x} ${bus.y})`} opacity={bus.opacity}>
            <IsoShadow x={2} y={0.6} r={1.6} unit={u} opacity={0.35} />
            <IsoBox x={0} y={0} w={4} d={1.2} h={1.3} unit={u} />
            {[0.4, 1.3, 2.2, 3.1].map((wx) => (
              <IsoFaceRect key={wx} face="left" at={1.2} a={[wx, wx + 0.6]} b={[0.6, 1.05]} unit={u} fill={palette.pale} />
            ))}
          </g>
        </g>
        <g transform={`translate(${width * 0.36 + plane.x} ${height * 0.2 + plane.y}) rotate(-28)`} opacity={plane.opacity}>
          <ellipse cx={0} cy={0} rx={130 * scale} ry={22 * scale} fill={palette.sky} />
          <polygon points={`${-10 * scale},0 ${40 * scale},${-95 * scale} ${70 * scale},${-95 * scale} ${40 * scale},0`} fill={palette.mid} />
          <polygon points={`${-10 * scale},0 ${40 * scale},${95 * scale} ${70 * scale},${95 * scale} ${40 * scale},0`} fill={palette.pale} />
          <polygon points={`${-110 * scale},0 ${-130 * scale},${-45 * scale} ${-105 * scale},${-45 * scale} ${-80 * scale},0`} fill={palette.mid} />
        </g>
      </svg>
    </AbsoluteFill>
  );
}
